select 1 as "exists" from "field" as "f" inner join "table_meta" as "t" on "t"."id" = "f"."table_id" where "t"."base_id" = $1 and "f"."deleted_time" is null and COALESCE("f"."is_pending", false) = false and "t"."deleted_time" is null and (
    "t"."provision_state" IN ($2)
    OR (
      "t"."id" IN ($3)
      AND "t"."provision_state" = 'pending'
    )
  ) and ("f"."is_lookup" = $4 or "f"."is_conditional_lookup" = $5 or "f"."type" in ($6, $7, $8, $9, $10, $11) or (
                  f.is_computed = true
                  AND f.type NOT IN ($12, $13, $14, $15, $16)
                )) limit $17

